css_template:
.mustache-renderer-container {
    border: 1px solid #ddd;
    border-radius: 4px;
    padding: 15px;
    margin: 10px 0;
    background-color: #f9f9f9;
}
.mustache-placeholder {
    color: #666;
    font-style: italic;
    padding: 10px;
    background-color: #f0f0f0;
    border-radius: 3px;
}

js_template:
// Mustache Renderer — client logic
(function() {
    const containers = document.querySelectorAll('.mustache-renderer-container');
    containers.forEach(container => {
        const template = container.dataset.template || '';
        const jsonData = container.dataset.json || '{}';
        const escapeHtml = container.dataset.escapeHtml !== 'false';
        try {
            const data = JSON.parse(jsonData);
            // Render with Mustache-style substitution
            let rendered = template.replace(/\{\{([^}]+)\}\}/g, (match, key) => {
                const val = data[key.trim()];
                if (val === undefined || val === null) return '';
                if (escapeHtml) {
                    const div = document.createElement('div');
                    div.textContent = String(val);
                    return div.innerHTML;
                }
                return String(val);
            });
            container.innerHTML = rendered;
        } catch (e) {
            container.innerHTML = '<div class="alert alert-danger">Parse error: ' + e.message + '</div>';
        }
    });
})();

// API Data Card — dynamic JSON loading
// Uses WET-BOEW data-wb-json for server-side rendering
// Falls back to direct fetch if WET-BOEW is not available
(function() {
    const cards = document.querySelectorAll('.api-data-card');
    if (cards.length === 0) return;

    cards.forEach(card => {
        const apiUrl = card.dataset.wbJson;
        if (!apiUrl) {
            card.innerHTML = '<div class="alert alert-warning">API Data Card: missing data-wb-json attribute</div>';
            return;
        }

        // If WET-BOEW is active, let it handle rendering
        if (typeof $.fn.wbJson !== 'undefined') {
            return; // WET-BOEW handles it
        }

        // Fallback: direct fetch
        fetch(apiUrl)
            .then(res => res.json())
            .then(data => {
                const titleKey = card.querySelector('[data-json-key]')?.dataset.jsonKey || 'title';
                const descKey = card.querySelector('.card-text')?.dataset.jsonKey || 'description';

                const title = getNestedValue(data, titleKey) || 'No title';
                const description = getNestedValue(data, descKey) || 'No description';

                const titleEl = card.querySelector('.card-title');
                const descEl = card.querySelector('.card-text');
                if (titleEl) titleEl.textContent = title;
                if (descEl) descEl.textContent = description;
            })
            .catch(err => {
                card.innerHTML = '<div class="alert alert-danger">Failed to load data: ' + err.message + '</div>';
            });
    });

    function getNestedValue(obj, path) {
        return path.split('.').reduce((current, key) => {
            return current && current[key] !== undefined ? current[key] : undefined;
        }, obj);
    }
})();
